import { useEffect, useState } from "react";
import { Trans, useTranslation } from "react-i18next";

const BASE = import.meta.env.BASE_URL;

type Credit = { file: string; authors: string; licenses: string; urls: string[] };

/**
 * Some LPC layers credit "https://opengameart.org/content/" with no page after it (the source
 * metadata has an empty slug). That address is a 404, so it is shown as text, not as a link.
 */
const BARE_BASE = /^https?:\/\/opengameart\.org\/content\/?$/;

/** Parses the CREDITS.csv generated by tools/build_character.py (quoted, comma-separated fields). */
function parse(csv: string): Credit[] {
  return csv
    .trim()
    .split("\n")
    .slice(1)
    .map((line) => {
      const fields = [...line.matchAll(/"([^"]*)"/g)].map((match) => match[1]);
      const [file = "", authors = "", licenses = "", urls = ""] = fields;
      return { file, authors, licenses, urls: [...new Set(urls.split("; ").filter(Boolean))] };
    });
}

/**
 * Sprite and font credits, required by the licenses (CC-BY-SA, OGA-BY, GPL and OFL). The
 * list itself (files, authors, licenses) comes from the CSV and isn't translated.
 */
export function Credits() {
  const { t } = useTranslation();
  const [credits, setCredits] = useState<Credit[]>([]);

  useEffect(() => {
    fetch(`${BASE}sprites/character/CREDITS.csv`)
      .then((response) => response.text())
      .then((text) => setCredits(parse(text)))
      .catch(() => setCredits([]));
  }, []);

  return (
    <main className="resume credits">
      <h1>{t("credits.title")}</h1>
      <p>
        <Trans
          i18nKey="credits.intro"
          components={{
            lpc: <a href="https://github.com/LiberatedPixelCup/Universal-LPC-Spritesheet-Character-Generator" />,
          }}
        />
      </p>
      <p>
        <a href={`${BASE}sprites/character/CREDITS.csv`}>{t("credits.downloadCsv")}</a>
      </p>
      <ul className="credits__list">
        {credits.map((credit) => (
          <li key={credit.file}>
            <p className="credits__file">{credit.file}</p>
            <p>{credit.authors}</p>
            <p className="credits__license">{credit.licenses}</p>
            <p className="credits__urls">
              {credit.urls.map((url) => {
                const text = url.replace(/^https?:\/\//, "");
                return BARE_BASE.test(url) ? (
                  <span key={url}>{text}</span>
                ) : (
                  <a key={url} href={url}>
                    {text}
                  </a>
                );
              })}
            </p>
          </li>
        ))}
      </ul>
    </main>
  );
}
